/**
 * T70 — bundled offline free-text vocabulary (allowlist of non-identifying words).
 *
 * The word set is generated by `scripts/build-log-vocabulary.mjs` into
 * `vocabulary.generated.ts` + `vocabulary.<hash>.bin`. Runtime uses the
 * generated blob (no network, no lazy fetch).
 */

import type { FreeTextVocabulary } from './types.ts'
import {
  FREE_TEXT_VOCABULARY_BLOB,
  FREE_TEXT_VOCABULARY_BIN_NAME,
  FREE_TEXT_VOCABULARY_BUILT_AT,
  FREE_TEXT_VOCABULARY_HASH,
  FREE_TEXT_VOCABULARY_MAX_AGE_DAYS,
  FREE_TEXT_VOCABULARY_VERSION,
  FREE_TEXT_VOCABULARY_WORD_COUNT,
} from './vocabulary.generated.ts'

export {
  FREE_TEXT_VOCABULARY_BIN_NAME,
  FREE_TEXT_VOCABULARY_BUILT_AT,
  FREE_TEXT_VOCABULARY_HASH,
  FREE_TEXT_VOCABULARY_MAX_AGE_DAYS,
  FREE_TEXT_VOCABULARY_VERSION,
  FREE_TEXT_VOCABULARY_WORD_COUNT,
}

/** @deprecated Prefer FREE_TEXT_VOCABULARY_VERSION (T70). */
export const INTERIM_VOCABULARY_VERSION = FREE_TEXT_VOCABULARY_VERSION

function buildWordSet(): ReadonlySet<string> {
  const set = new Set<string>()
  if (FREE_TEXT_VOCABULARY_BLOB.length === 0) return set
  let start = 0
  for (let i = 0; i <= FREE_TEXT_VOCABULARY_BLOB.length; i++) {
    if (i === FREE_TEXT_VOCABULARY_BLOB.length || FREE_TEXT_VOCABULARY_BLOB.charCodeAt(i) === 0) {
      if (i > start) set.add(FREE_TEXT_VOCABULARY_BLOB.slice(start, i))
      start = i + 1
    }
  }
  return set
}

const WORD_SET = buildWordSet()

export const bundledVocabulary: FreeTextVocabulary = {
  version: `${FREE_TEXT_VOCABULARY_VERSION}+${FREE_TEXT_VOCABULARY_HASH}`,
  has(word: string): boolean {
    const key = word.trim().toLowerCase()
    if (key.length === 0) return false
    return WORD_SET.has(key)
  },
}

/** @deprecated Alias for {@link bundledVocabulary}. */
export const interimVocabulary = bundledVocabulary

/** Default vocabulary for free-text call sites (T69/T70). */
export function defaultFreeTextVocabulary(): FreeTextVocabulary {
  return bundledVocabulary
}

/** True when spelling is a bundled non-identifying word (T66 propagation skip). */
export function isVocabularyWord(spelling: string): boolean {
  return bundledVocabulary.has(spelling)
}
